{
  .stpps.init[tables[] except `currlog`heartbeat`logmsg`svrstoload];
  .stpps.attrstrip[.stpps.t];

  // Table UPD functions attach the current timestamp by default, if STP is chained these do nothing
  $[.sctp.chainedtp;
    .stplg.updtab:(.stpps.t!(count .stpps.t)#{[x;y] x}),.stplg.updtab;
    .stplg.updtab:(.stpps.t!(count .stpps.t)#{(enlist(count first x)#y),x}),.stplg.updtab
    ]
  }

{
  if[not `schemafile in key .proc.params;.lg.e[`loadschema;"Schema file required!"];exit 1];
  @[.proc.loadf;raze .proc.params[`schemafile];{.lg.e[`loadschema;"Failed to load schema file!"];exit 1}];
 }

{[batch]
  // Handle bad batch mode, see whether STP is chained or default
  if[not all batch in/: key'[.stplg`upd`zts];'"mode ",(string batch)," must be defined in both .stplg.upd and .stplg.zts"];
  chainmode:$[.sctp.chainedtp;`chained;`def];

  // Set inner UPD and ZTS behaviour from batch mode, then set outer functions based on whether STP is chained
  .stplg.updmsg:.stplg.upd[batch];
  .stplg.ts:.stplg.zts[batch];
  .u.upd:.stpps.upd[chainmode];
  .dotz.set[`.z.ts;
    {[f;x] @[;x;()]each f}
      (@[value;.dotz.getcommand[`.z.ts];{{}}];
      .stpps.zts[chainmode])];

  // Error mode - error trap UPD to write failed updates to separate TP log
  if[.stplg.errmode;
    .stp.upd:.u.upd;
    .u.upd:{[t;x] .[.stp.upd;(t;x);{.stplg.badmsg[x;y;z]}[;t;x]]}
   ];

  // Default the timer to 1 second if not set
  if[not system "t";.lg.o[`timer;"defaulting timer to 1000ms"];system"t 1000"];
 }

{
  // Set up the update and publish functions
  setup[.stplg.batchmode];
  // If process is a chained STP then subscribe to the main STP, if not, load schema file
  $[.sctp.chainedtp;.sctp.init[];loadschemas[]];
  // Set up pubsub mechanics and table schemas
  generateschemas[];
  // Set up logs and log handles using name of process as an identifier
  .stplg.init[string .proc.procname];
 }

{
  if[not x~0i;.lg.e[`stpexit;"Bad exit!"];:()];
  .lg.o[`stpexit;"Exiting process"];

  // flushing in memory data to disk during unexpected shutdown when batchmode is set to memorybatch
  if[.stplg.batchmode=`memorybatch;
     .lg.o[`stpexit;"STP shutdown unexpectedly, batchmode = `memorybatch, therefore flushing any remaining data to the on-disk log file"];
     .stplg.zts.memorybatch[];
     .lg.o[`stpexit; "Complete!"]
    ];

  // exit before logs are touched if process is an sctp NOT in create mode
  if[.sctp.chainedtp and not .sctp.loggingmode=`create; :()];
  .lg.o[`stpexit;"Closing off log files"];
  .stpm.updmeta[.stplg.multilog][`close;.stpps.t;.z.p];
  .stplg.closelog each .stpps.t;
 }

{[envvar; default]
 if[""~getenv[envvar];
  .lg.o[`init;(string envvar)," is not defined. Defining it to ",val:qhome[],"/",default];
  setenv[envvar; val]];}

{[dict;t;x]
      /- i=dependency. j=version
      j:vs[".";]'[string dict[d:`$first " " vs x]];
      i:"." vs last " " vs x;
      /- check app for current dependency exists
      if[not d in key dict;[.lg.e[`config;(raze/) string t[`app]," ", string t[`version] ," requires ",string d," ",sv[".";i],". Current version not supplied"]]];
      checkvers[i;;d;t]'[j]}

{[path]
      /- check config files are supplied
      if[2<=count path;
        /- check TorQ config file is supplied
        if[()~key hsym last path;[.lg.e[`config;"TorQ config file not supplied ",string last path]]];
        /-load config csv files
        a,:raze {("SSS";enlist ",") 0: hsym[x]} each path;
        /- check for kdb verion
        if[not `kdb in a[`app];a,:(`kdb;`$(string .z.K),".",string .z.k;`)];
        /- get current app versions
        dict:exec version by app from a;
        /- update table to contain string dependencies
        t:update vs[";";]each string dependency from (select from a where dependency<>`);
        /-check each dependency within t
        {[t;dict] runchk[dict;t;]'[t[`dependency]]}[;dict]'[t]]}

{[path;level]
        /- check if KDBSERVCONFIG exists
        keyservconf:$[not ""~ksc:getenv`KDBSERVCONFIG;
          key hsym servconf:`$ksc,"/",path;
          ()];
        /- check if KDBAPPCONFIG exists
        keyappconf:$[not ""~kac:getenv`KDBAPPCONFIG;
          key hsym appconf:`$kac,"/",path;
          ()];

        /-if level=2 then all files are returned regardless
        if[level<2;
          if[()~keyappconf;
            appconf:()];
          if[()~keyservconf;
            servconf:()]];

        /-get KDBCONFIG path
        conf:`$(kc:getenv[`KDBCONFIG]),"/",path;

        /-if level is non-zero return appconfig, servconfig and config files
        (),$[level;
          appconf,servconf,conf;
          first appconf,servconf,conf]}

{[file]
 // Updates the process table to convert strings to integer and symbols
 updateprocs:{
 	// Gets the value of the input expression and returns it as an integer
 	// list if the expression can be evaluated, else return null
 	errcheckport:{@[{"I"$string value x};x;0N]};

 	// begin updating process file table
 	t:update port:errcheckport each .rmvr.removeenvvar each port from x;
 	t:update host:"S"$.rmvr.removeenvvar each host from t;
 	t:update procname:"S"$.rmvr.removeenvvar each procname from t;
 	t:update proctype:"S"$.rmvr.removeenvvar each proctype from t;
 	// return updated process file table
 	t
 	};
 // error trap loading and processing of process file and returns finished table
 @[updateprocs ("****";enlist",")0:;file;
 {.lg.e[`procfile;"failed to read process file ",(string x)," : ",y]}[file]]
 }

{
 	// Gets the value of the input expression and returns it as an integer
 	// list if the expression can be evaluated, else return null
 	errcheckport:{@[{"I"$string value x};x;0N]};

 	// begin updating process file table
 	t:update port:errcheckport each .rmvr.removeenvvar each port from x;
 	t:update host:"S"$.rmvr.removeenvvar each host from t;
 	t:update procname:"S"$.rmvr.removeenvvar each procname from t;
 	t:update proctype:"S"$.rmvr.removeenvvar each proctype from t;
 	// return updated process file table
 	t
 	}

{[file]
 //order of preference for hostnames
 prefs:(.z.h;`$"." sv string "i"$0x0 vs .z.a;`localhost);
 res:@[{t:select from readprocs[file] where not null host;
 // allow host=localhost for ease of startup
 $[not any null `.proc req;
 	select from t where proctype=.proc.proctype,procname=.proc.procname;
 	select from t where abs[port]=abs system"p",(lower[host]=lower .z.h) or (host=`localhost) or host=`$"." sv string "i"$0x0 vs .z.a]
 	};file;{.err.ex[`init;"failed to read process file ",(string x)," : ",y;2]}[file]];
 	if[0=count res;
 	.lg.o[`readprocfile;"failed to read any rows from ",(string file)," which relate to this process; Host=",(string .z.h),", IP=",("." sv string "i"$0x0 vs .z.a),", port=",string system"p"];
 	:`host`port`proctype`procname!(`;0;proctype;procname)];
 	// if more than one result, take the most preferred one
 output:$[1<count res;
 	// map hostnames in res to order of preference, select most preferred
 	first res iasc prefs?res[`host];
 	first res];
        if[not output[`host]in prefs;
                .err.ex[`readprocfile;"Current host does not match host specified in ",string[file],". Parameters are host: ", string[output`host], ", port: ", string[output`port], ", proctype: ", string[output`proctype], ", procname: ",string output`procname;1]];
 // exit if no port passed via command line or specified in config
 if[null[output`port]&0i=system"p";
 	.err.ex[`readprocfile;"No port number passed via -p flag or no port number found in ",string[file],". Parameters are host: ", string[output`host], ", proctype: ", string[output`proctype], ", procname: ",string output`procname;1]];
 // .finspace.enabled flag here is a temporarily bug fix for Finspace DEV clusters - port is set later so is empty when we reach this point. AWS investigating
 if[not[.finspace.enabled]&not[output[`port] = system"p"]& 0i = system"p";
 	@[system;"p ",string[output[`port]];.err.ex[`readprocfile;"failed to set port to ",string[output[`port]]]];
 	.lg.o[`readprocfile;"port set to ",string[output[`port]]]
 	];
 output
 }

{t:select from readprocs[file] where not null host;
 // allow host=localhost for ease of startup
 $[not any null `.proc req;
 	select from t where proctype=.proc.proctype,procname=.proc.procname;
 	select from t where abs[port]=abs system"p",(lower[host]=lower .z.h) or (host=`localhost) or host=`$"." sv string "i"$0x0 vs .z.a]
 	}

{[logdir;filename;alias;handle]
 if[not (h:string handle) in (enlist "1";enlist "2");
 	'"handle must be 1 or 2"];
 .lg.o[`logging;"re-directing ",h," to",f:" ",logdir,"/",filename];
 @[system;s;{.lg.e[`logging;"failed to redirect ",x," : ",y]}[s:h,f]];
 if[not null `$alias; createalias[logdir;filename;alias]]}

{[logdir;filename;alias]
 $[.z.o like "w*";
 	[if[not()~key hsym`$a:ssr[logdir,"/",alias;"/";"\\"];
 		 	.lg.o[`logging;"removing existing alias using command ",s:"del ",a];
 		@[system;s;{.lg.e[`init;"failed to remove alias ",x," : ",y]}[s]]];
 		 .lg.o[`logging;"creating alias using command ",s:"mklink ",a," ",ssr[logdir,"/",filename;"/";"\\"]];
 		 res:@[system;s;{.lg.o[`init;"failed to create symbolic link ",x," : ",y];`fail}[s]];
 		 if[`fail~res;
 		    .lg.o[`logging;"creating alias using command ",s:"mklink /h ",a," ",ssr[logdir,"/",filename;"/";"\\"]];
 		    @[system;s;{.lg.e[`init;"failed to create hard link ",x," : ",y]}[s]]] ];
 		[.lg.o[`logging;"creating alias using command ",s:"ln -sf ",filename," ",logdir,"/",alias];
 	 @[system;s;{.lg.e[`init;"failed to create alias ",x," : ",y]}[s]]]]}

{[]
 .lg.o[`logging;"creating standard out and standard err logs"];
 createlog[getenv`KDBLOG;procname;logtimestamp[];`suppressalias in key params]}

{[reload;x]
  if[not[reload]&x in loadedf;.lg.o[`fileload;"already loaded ",x];:()];
  .lg.o[`fileload;"loading ",x];
  $[`debug in key params;system"l ",x;@[system;"l ",x;{.lg.e[`fileload;"failed to load ",x," : ",y]}[x]]];
  // if we got this far, file is loaded
  loadedf,:enlist x;
  .lg.o[`fileload;"successfully loaded ",x]
 }

{
 .lg.o[`fileload;"loading q and k files from directory ",x];
 // Check the directory exists
 $[()~files:key hsym `$x; .lg.o[`fileload;"specified directory ",x," doesn't exist"];
 // Try to read in a load order file
 	[
        	$[`order.txt in files:key hsym `$x;
                	[.lg.o[`fileload;"found load order file order.txt"];
                 	order:(`$read0 `$x,"/order.txt") inter files;
                 	.lg.o[`fileload;"loading files in order "," " sv string order]];
                	order:`symbol$()];
        	files:files where any files like/: ("*.q";"*.k");
        	// rearrange the ordering
        	files:order,files except order;
        	loadf each (x,"/"),/:string files
 	]
 ];
 }

{
 file:x,(string y),".q";
 $[()~key hsym`$file;
 	.lg.o[`fileload;"config file ",file," not found"];
 	[.lg.o[`fileload;"config file ",file," found"];
 	 loadf file]]}

{[params]
 // work out which are the potential variables to override
 ov:key[params] where key[params] like ".*";
 // can only can do those which are already set
 ov:ov where @[{value x;1b};;0b] each ov;
 if[count ov;
 	.lg.o[`init;"attempting to override variables ",("," sv string ov)," from the command line"];
 	{if[not (abs t:type value y) within (1;-1+count .Q.t);
 		.lg.e[`init;"Cannot override ",(string y)," as it is not a basic type"];
 		:()];
 	 // parse out the values
 	 vals:(upper .Q.t abs t)$'x[y];
 	 if[t<0;vals:first vals];
 	 // check for nulls
 	 if[any null each vals; .lg.e[`init;"Cannot override ",(string y)," with command line parameters as null values have been supplied"]];
 	 .lg.o[`init;"Setting ",(string y)," to ",-3!vals];
 	 set[y;vals]}[params] each ov]}

{if[not (abs t:type value y) within (1;-1+count .Q.t);
 		.lg.e[`init;"Cannot override ",(string y)," as it is not a basic type"];
 		:()];
 	 // parse out the values
 	 vals:(upper .Q.t abs t)$'x[y];
 	 if[t<0;vals:first vals];
 	 // check for nulls
 	 if[any null each vals; .lg.e[`init;"Cannot override ",(string y)," with command line parameters as null values have been supplied"]];
 	 .lg.o[`init;"Setting ",(string y)," to ",-3!vals];
 	 set[y;vals]}

{[ext;dir]
 $[""~getenv dir;
  .lg.o[`init;"Environment variable ",string[dir]," not set, not loading specific ",ext," code"];
  loaddir getenv[dir],ext
   ];
 }

{[cmd]
 .lg.o[`system;"executing system command: ",cmd];
 catcherror:{[cmd;error] .lg.e[`system;"failed to execute ",cmd,": ",error];'error};
 @[{result:system x;.lg.o[`system;"successfully executed"];result};cmd;catcherror[cmd;]]
 }

{[envvar;cnfgpath]
 evstring:string envvar;
 if[""~getenv[envvar];
 	.lg.o[`fileload;"environment variable ",evstring," not set, not loading this config"];
 	:();
 ];
 set[cnfgpath;getenv[envvar],"/settings/"];
 .lg.o[`fileload;"environment variable ",evstring," set, loading this config"];
 .proc.loadconfig[getenv[envvar],"/settings/";] each `default,.proc.parentproctype,.proc.proctype,.proc.procname
 }

{[id;a]
  .lg.o[id;"attempting to run: ",.Q.s1 a];
  success:$[`debug in key .proc.params;{value x;1b}a;@[{value x;1b};a;{[id;a;x].lg.e[id;x," error - failed to run: ",.Q.s1 a];0b}[id;a]]];
  if[not success;:()];
  .proc.initexecuted,:a;
  .lg.o[id;"run successful: ",.Q.s1 a];
 }

{
  // command line functions executed first
  if[not`initlist in key .proc.params;:.lg.o[`init;"no initialisation functions found in cmd line args"]];
  {.proc.try[`init;(x;`)]}each .proc.params`initlist;
 }

{[loglevel;proctype;proc;id;message]
 if[0<0^pubmap[loglevel];
  // check the publish function exists
  if[@[value;`.ps.initialised;0b];
   .ps.publish[`logmsg;enlist`time`sym`proctype`host`loglevel`id`message!(.proc.cp[];proc;proctype;.z.h;loglevel;id;message)]]]}

{
 width:80;
 format:{"#",(floor[m]#" "),y,((ceiling m:0|.5*x-count y)#" "),"#"}[width - 2];
 blank:"#",((width-2)#" "),"#";
 full:width#"#";
 // print the banner
 -1 full;
 -1 blank;
 -1 format"TorQ v",.proc.getversion[];
 -1 format"Data Intellect";
 -1 format"We turn big data problems into smart data solutions";
 -1 blank;
 -1 format"For questions, comments, requests or bug reports please contact us";
 -1 format"w :     www.dataintellect.com";
 -1 format"e : torqsupport@dataintellect.com";
 -1 blank;
 -1 format"Running on ","kdb+ ",(string .z.K)," ",string .z.k;
 if[count customtext:.proc.getapplication[];-1 format each customtext;-1 blank]; // prints custom text from file
 -1 full;}

{[paramdict;reqparams]
 if[count missing:(reqparams,:()) except key paramdict;
 	.lg.e[`init;"missing required command line parameter(s) "," " sv string missing];
 	usage[]]}

{[reqenv]
 if[count missing:reqenv where 0=count each getenv each reqenv,:();
 	.lg.e[`init;"required environment variable(s) not set - "," " sv string missing];
 	usage[]]}

{[variable]
 if[null value variable;
 	.lg.e[`init;"Variable ",(string variable)," is null but must be set"];
 	usage[]]}

{
 // positions of {}
 pos:ss[x]each"{}";
 // check the formatting is ok
 $[0=count first pos; :x;
 1<count distinct count each pos; '"environment variable contains unmatched brackets: ",x;
 (any pos[0]>pos[1]) or any pos[0]<prev pos[1]; '"failed to match environment variable brackets on supplied string: ",x;
 ()];

 // cut out each environment variable, and retrieve the meaning
 // ascertain if string is an env var by checking if first char is a {
 raze {$["{"~first x;resolveandcheckenvvar[x];x]}each (raze flip 0 1+pos) cut x}

{[s]
 ev:getenv[`$1 _ -1 _ s];
 if[""~ev;.lg.w[`resolveandcheckenvvar;"warning, could not resolve environment variable: ",s]];
 ev}

{[zcommand]
    zcommand:`$last"."vs string zcommand;
    $[`ORIG in key ns:` sv `.dotz,zcommand;
        .dotz.set[zcommand;ns[`ORIG]];
        ![.dotz.getnamespace[];();0b;enlist zcommand]];}

{
    $[.finspace.enabled;
 @[neg 1;format x;()];
 if[logtodisk;@[neg logh;format x;()]]];
    if[logtomemory; `.usage.usage upsert x];
    ext[x]}

{[logdir;logname;timestamp;suppressalias]
 basename:"usage_",(string logname),"_",(string timestamp),".log";
 // Close the current log handle if there is one
 if[logh; @[hclose;logh;()]];
 // Open the file
 .lg.o[`usage;"creating usage log file ",lf:logdir,"/",basename];
 logh::hopen hsym`$lf;
 // Create an alias
 if[not suppressalias;
 	.proc.createalias[logdir;basename;"usage_",(string logname),".log"]];
 }

{[file]
 // Remove leading backtick from symbol columns, convert a and w columns back to integers
 update zcmd:`$1 _' string zcmd, procname:`$1 _' string procname, proctype:`$1 _' string proctype, u:`$1 _' string u,
 	a:"I"$-1 _' a, w:"I"$-1 _' w from
 // Read in file
 @[{update "J"$'" " vs' mem from flip (cols .usage.usage)!("PJJSSSC*S***JS";"|")0:x};hsym`$file;{'"failed to read log file : ",x}]}

{ / cleanup closed or idle entries
    if[count w0:exec w from`.clients.clients where not .dotz.livehn w;
        update endp:.proc.cp[],w:0Ni from`.clients.clients where w in w0];
    if[.clients.MAXIDLE>0;
        hclose each exec w from`.clients.clients where .dotz.liveh w,lastp<.proc.cp[]-.clients.MAXIDLE];
    delete from`.clients.clients where not .dotz.liveh w,endp<.proc.cp[]-.clients.RETAIN;}

{[result;W]
    cleanup[];
    `.clients.clients upsert(W;.dotz.ipa .z.a;.z.u;.z.a;0Nd;0n;0Ni;0Ni;(`);(`);0Ni;0Ni;zp;0Np;zp:.proc.cp[];0i;0i;0j);
    if[INTRUSIVE;
        neg[W]"neg[.z.w]\"update k:\",(string .z.k),\",K:\",(-3!.z.K),\",c:\",(-3!.z.c),\",s:\",(-3!system\"s\"),\",o:\",(-3!.z.o),\",f:\",(-3!.z.f),\",pid:\",(-3!.z.i),\",port:\",(-3!system\"p\"),\" from`.clients.clients where w=.z.w\""];
    result}

{[u;a;h;p]
  if[u in key groupinfo;'"pm: cannot add user with same name as existing group"];
  user,:(u;a;h;p)}

{[n;d]
  if[n in key user;'"pm: cannot add group with same name as existing user"];
  groupinfo,:(n;d)}

{[u;g]
  if[not g in key groupinfo;'"pm: no such group, .pm.addgroup first"];
  if[not (u;g) in usergroup;usergroup,:(u;g)];}

{[u;r]
  if[not r in key roleinfo;'"pm: no such role, .pm.addrole first"];
  if[not (u;r) in userrole;userrole,:(u;r)];}

{[u;unew;p] adduser[unew;ul[0] ;ul[1]; value (string (ul:raze exec authtype,hashtype from user where id=u)[1]), " string `", p];
 addtogroup[unew;` sv value(1!usergroup)[u]];
 assignrole[unew;` sv value(1!userrole)[u]]}

{[f;a]
  d:enlist[`]!enlist[::];
  d:d,$[not ca:count a; ();
        f~`select; ();
        (1=count a) and (99h=type first a); first a;
        /if projection first obtain a list of function and fixed parameters (fnfp)
        /pargs contains all projected args with :: marking unfixed positions
        /allargs fills the full param list, then replaces :: positions with actual args a
        104h=type value f; [fnfp:value value f;params:value[fnfp 0][1];pargs:1_ fnfp;allargs:(count params)#enlist[::];allargs[til count pargs]:pargs;allargs[where 101h=type each allargs]:a;params!allargs];
        /get paramaters and make a dictionary with the arguments
        101h<>type fp:value[value[f]][1]; fp!a;
        ((),(`$string til ca))!a
       ];
  d}

{[u;t;rw;pr]
  if[fchk[u;ALL;()]; :1b];
  if[pr and not t in key 1!access; :1b];
  t: ALL,t;
  g:raze over (exec groupname by user from usergroup)\[u]; / groups can contain groups - chase all
  exec 0<count i from access where object in t, entity in g, level in (`read`write!(`read`write;`write))[rw]}

{[u;q;b;pr]
  if[not fchk[u;`select;()]; $[b;'err[`quer][]; :0b]];  / must have 'select' access to run free form queries
  / update or delete in place
  if[((!)~q[0])and(11h=type q[1]);
    if[not achk[u;first q[1];`write;pr]; $[b;'err[`updt][first q 1]; :0b]];
    $[b; :qexe q; :1b];
  ];
  / nested query
  if[isq q 1; $[b; :qexe @[q;1;.z.s[u;;b;pr]]; :1b]];
  / select on named table
  if[11h=abs type q 1;
     t:first q 1;
     / virtual select
     if[t in key virtualtable;
       vt:virtualtable[t];
       q:@[q;1;:;vt`table];
       q:@[q;2;:;enlist first[q 2],vt`whereclause];
     ];
     if[not achk[u;t;`read;pr]; $[b; 'err[`selt][t]; :0b]];
     $[b; :qexe q; :1b];
  ];
  / default - not specifally handled, require superuser
  if[not fchk[u;ALL;()]; $[b; 'err[`selx][]; :0b]];
  $[b; :qexe q; :1b]}

{[u;e;b;pr]
  / get names of all defined variables to look for references to in expression
  rt:raze .api.varnames[;"v";1b]'[.api.allns[]];
  / allow public tables to always be accessed
  rt:rt except distinct exec object from access where entity=`public;
  / flatten expression & tokenize to extract any possible variable references
  pq:`$distinct -4!raze(str flatten e),'" ";
  / filter expression tokens to those matching defined variables
  rqt:rt inter pq;
  prohibited:rqt where not achk[u;;`read;pr] each rqt;
  if[count prohibited;'" | " sv .pm.err[`selt] each prohibited];
  $[b; :exe e; :1b]}

{[u;e;b;pr]
  / store initial expression to use with value
  ie:e;
  e:$[10=type e;parse e;e];
  / variable reference
  if[isvar f:first e;
    if[not achk[u;f;`read;pr]; $[b;'err[`selt][f]; :0b]];
