  partdirs:$[writedownmode in `partbyenum`partbyfirstchar;
             p where 0<count each key each p:` sv' ((-1_` vs p),/:key p:.Q.par[hsym dir;pt;`]),\: tabname;
             ` sv' tabledir,/:key tabledir:.Q.par[hsym dir;pt;tabname]];
